$error=null;$rows=[];$cats=[];$offers=[];$combo=[];$comboProducts=[];$customerCtx=['scope'=>'guest','is_member'=>false];$q=trim((string)($_GET['q']??''));$category=(int)($_GET['category']??0);$sort=(string)($_GET['sort']??'featured');
try{$pdo=ps23_db();cm_ensure($pdo);pscms_ensure($pdo);$ctx=ps23_context($pdo);$set=ps23_settings($pdo,$ctx['organization_id']);if(empty($set['storefront_enabled']))throw new RuntimeException('The product portal is temporarily unavailable.');$customerCtx=cm_customer_context($pdo,$ctx['organization_id']);$rows=ps23_catalog($pdo,$ctx['organization_id'],$q,$category);foreach($rows as &$r)$r['customer_price']=cm_catalog_price($pdo,$ctx['organization_id'],$r,$customerCtx,1,(float)$r['volume_points']);unset($r);if($sort==='price_low')usort($rows,fn($a,$b)=>(float)$a['customer_price']['unit_price']<=>(float)$b['customer_price']['unit_price']);elseif($sort==='price_high')usort($rows,fn($a,$b)=>(float)$b['customer_price']['unit_price']<=>(float)$a['customer_price']['unit_price']);elseif($sort==='name')usort($rows,fn($a,$b)=>strcasecmp((string)$a['product_name'],(string)$b['product_name']));elseif($sort==='vp_high')usort($rows,fn($a,$b)=>(float)$b['volume_points']<=>(float)$a['volume_points']);$cats=ps23_categories($pdo,$ctx['organization_id']);$offers=cm_promotions($pdo,$ctx['organization_id'],(string)$customerCtx['scope'],null);$combo=pscms_payload($pdo)['content'];if(($combo['combo_enabled']??'0')==='1'){$ids=json_decode((string)($combo['combo_product_ids']??''),true);if(!is_array($ids))$ids=[];$ids=array_values(array_unique(array_filter(array_map('intval',$ids))));if(!$ids)$ids=array_values(array_unique(array_filter(array_map('intval',[$combo['combo_product_1']??0,$combo['combo_product_2']??0,$combo['combo_product_3']??0]))));foreach($ids as $id){try{$comboProducts[]=ps23_product($pdo,$ctx['organization_id'],$id);}catch(Throwable $ignored){}}if(count($comboProducts)<2)$comboProducts=[];}}catch(Throwable $e){$error=$e->getMessage();}
function avlabel(string $status):string{return match($status){'available'=>'Available now','limited'=>'Limited stock • request allowed','unavailable'=>'Availability confirmed at review',default=>'Availability confirmed at review'};}
function avclass(string $status):string{return $status==='unavailable'?'review':$status;}
function shop_style(string $style):string{return in_array($style,['green','bronze','silver','gold','blue','purple','coral'],true)?$style:'green';}
