']):?><div class="price-stack"><span class="old-price">MRP <?=ps23_money($row['mrp'])?></span><span class="member-price"><?=ps23_money($price['unit_price'])?></span><span class="saving">Save <?=ps23_money($price['saving'])?></span></div><div class="meta"><?=str_starts_with((string)$price['pricing_source'],'MEMBER:')?'Your assigned member price':'Eligible offer price'?> • <?=ps23_h(rtrim(rtrim(number_format((float)$row['volume_points'],3,'.',''),'0'),'.'))?> VP</div><?php else:?><div class="product-price-row"><span class="price"><?=ps23_money($row['mrp'])?></span><span class="vp"><?=ps23_h(rtrim(rtrim(number_format((float)$row['volume_points'],3,'.',''),'0'),'.'))?> VP</span></div><div class="meta"><?=!empty($customerCtx['is_member'])?'Assigned-tier price unavailable • MRP shown':'Current source-listed MRP'?></div><?php endif;?><div class="product-actions"><a class="store-btn" href="product.php?id=<?=(int)$row['id']?>">Details</a><button class="store-btn primary" type="button" data-add-product="<?=(int)$row['id']?>">Add to Cart</button></div></div></article><?php endforeach;?><?php if(!$rows):?><div class="card empty" style="grid-column:1/-1">No matching active products. Try another search or category.</div><?php endif;?></section></section></div>
